with up as (update public.artist_discography d set bandcamp_item_id=x.id, bandcamp_item_type=x.ty, updated_at=now() from json_to_recordset('[{"s": "rafiki", "t": "Good Luck (with Squidworks)", "ty": "album", "id": 2339875409}]') as x(s text,t text,ty text,id bigint) where d.artist_slug=x.s and lower(d.title)=lower(x.t) and d.bandcamp_item_id is null returning 1) select count(*) from up;